 using System;
 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // --- FormatPhoneNumber ---

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         StringAssert.StartsWith(result, "(555)");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         StringAssert.EndsWith(result, "4567");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ContainsDashSeparator()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         StringAssert.Contains(result, "-");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsExpectedFormat()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.AreEqual("(555) 123-4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
     {
         Assert.ThrowsException<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));
     }

     [TestMethod]
     [DataRow("123")]
     [DataRow("12345678901")]
     public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsException<ArgumentException>(
             () => _formatter.FormatPhoneNumber(digits));
     }

     // --- BuildGreeting ---

     [TestMethod]
     public void BuildGreeting_DefaultTitle_StartsWithDearMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         StringAssert.StartsWith(result, "Dear Mr.");
     }

     [TestMethod]
     public void BuildGreeting_AnyInput_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         StringAssert.EndsWith(result, ",");
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_ContainsTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         StringAssert.Contains(result, "Dr.");
     }

     [TestMethod]
     public void BuildGreeting_ValidInput_ReturnsExpectedFormat()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.AreEqual("Dear Dr. Johnson,", result);
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_EmptyOrWhitespaceName_ThrowsArgumentException(string name)
     {
         Assert.ThrowsException<ArgumentException>(
             () => _formatter.BuildGreeting(name));
     }

     [TestMethod]
     public void BuildGreeting_NullName_ThrowsArgumentNullException()
     {
         Assert.ThrowsException<ArgumentNullException>(
             () => _formatter.BuildGreeting(null!));
     }

     // --- GenerateSlug ---

     [TestMethod]
     public void GenerateSlug_SimpleTitle_ReturnsLowercaseSlug()
     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithSpecialChars_ContainsOnlyValidChars()
     {
         var result = _formatter.GenerateSlug("C# is Great!");

         StringAssert.Matches(result, new System.Text.RegularExpressions.Regex(@"^[a-z0-9\-]+$"));
     }

     [TestMethod]
     public void GenerateSlug_TitleStartingWithSpecialChars_DoesNotStartWithDash()
     {
         var result = _formatter.GenerateSlug("  --Hello");

         Assert.IsFalse(result.StartsWith('-'));
     }

     [TestMethod]
     public void GenerateSlug_TitleEndingWithSpecialChars_DoesNotEndWithDash()
     {
         var result = _formatter.GenerateSlug("Hello--  ");

         Assert.IsFalse(result.EndsWith('-'));
     }

     [TestMethod]
     public void GenerateSlug_MultipleSpaces_CollapsesToSingleDash()
     {
         var result = _formatter.GenerateSlug("Hello    World");

         StringAssert.Contains(result, "hello-world");
         Assert.IsFalse(result.Contains("--"));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void GenerateSlug_EmptyOrWhitespaceTitle_ThrowsArgumentException(string title)
     {
         Assert.ThrowsException<ArgumentException>(
             () => _formatter.GenerateSlug(title));
     }

     [TestMethod]
     public void GenerateSlug_NullTitle_ThrowsArgumentNullException()
     {
         Assert.ThrowsException<ArgumentNullException>(
             () => _formatter.GenerateSlug(null!));
     }

     // --- FormatCurrency ---

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(9.99m);

         StringAssert.StartsWith(result, "$");
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         StringAssert.StartsWith(result, "€");
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_EndsWithTwoDecimalPlaces()
     {
         var result = _formatter.FormatCurrency(100m);

         StringAssert.EndsWith(result, ".00");
     }

     [TestMethod]
     public void FormatCurrency_NegativeAmount_ContainsMinusSign()
     {
         var result = _formatter.FormatCurrency(-5.50m);

         StringAssert.Contains(result, "-");
     }

     [TestMethod]
     public void FormatCurrency_PreciseAmount_ReturnsExpectedFormat()
     {
         var result = _formatter.FormatCurrency(1234.56m, "£");

         Assert.AreEqual("£1234.56", result);
     }
 }
